(() => {
  'use strict';
  const M=window.PeregriniEditorModel,client=window.PeregriniEditorGitHub.createClient();
  const $=id=>document.getElementById(id),escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let data=null,base=null,workIndex=0,formatIndex=0,dirty=false,busy=false;
  let vocabularyData=null;
  let draftTimer, pendingDraft=null,publicationTimer,publicationHash='',publicationRound=0;
  const drafts=window.PeregriniDrafts.create({getItem:k=>localStorage.getItem(k),setItem:(k,v)=>localStorage.setItem(k,v),removeItem:k=>localStorage.removeItem(k)});
  function draftNotice(text,error=false){$('draft-status').textContent=text;$('draft-status').classList.toggle('error',error);}
  function saveDraft(){clearTimeout(draftTimer);if(!data||!dirty||pendingDraft)return;try{const d=drafts.save(data,base);draftNotice('Rascunho salvo neste navegador às '+new Date(d.savedAt).toLocaleTimeString('pt-BR')+'.');}catch{draftNotice('Não foi possível guardar o rascunho neste navegador. Use Baixar cópia para preservar seu texto.',true);}}
  function findDraft(){try{pendingDraft=drafts.read();if(pendingDraft&&JSON.stringify(pendingDraft.data)===JSON.stringify(base)){drafts.remove();pendingDraft=null;}}catch{pendingDraft=null;draftNotice('Não foi possível ler o rascunho local.',true);}$('draft-recovery').hidden=!pendingDraft;}
  function clearDraft(){clearTimeout(draftTimer);try{drafts.remove();}catch{}pendingDraft=null;$('draft-recovery').hidden=true;}
  function exportData(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)+'\n'],{type:'application/json;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function stopPublication(){clearTimeout(publicationTimer);publicationRound++;}
  async function checkPublication(automatic=false){if(!publicationHash)return;const round=publicationRound,hash=publicationHash;$('publication-check').disabled=true;try{const ready=await window.PeregriniPublication.check(hash);if(round!==publicationRound)return;if(ready){$('publication-state').textContent='Publicado: esta versão dos textos já está disponível no site.';clearTimeout(publicationTimer);try{sessionStorage.removeItem('peregrini:pending-publication');}catch{}return;}$('publication-state').textContent='Salvo no GitHub. Esta versão ainda não foi confirmada no site.';}catch{if(round!==publicationRound)return;$('publication-state').textContent='Salvo no GitHub. Não foi possível confirmar a publicação; consulte o processo no GitHub.';}finally{if(round===publicationRound)$('publication-check').disabled=false;}if(automatic&&Date.now()-publicationStarted<300000)publicationTimer=setTimeout(()=>checkPublication(true),10000);}
  let publicationStarted=0;
  function watchPublication(hash){stopPublication();publicationHash=hash;publicationStarted=Date.now();$('publication').hidden=false;try{sessionStorage.setItem('peregrini:pending-publication',hash);}catch{}checkPublication(true);}
  const work=()=>data?.works[workIndex],version=()=>work()?.variants[formatIndex];
  function notice(text,error=false){$('notice').textContent=text;$('notice').classList.toggle('error',error);}
  function status(){ if($('vocabulary-fields'))$('vocabulary-fields').disabled=busy||!!pendingDraft; $('vocabulary-editor').querySelectorAll('button').forEach(b=>b.disabled=busy||!!pendingDraft); $('dirty-state').textContent=dirty?'Alterações ainda não enviadas':'Sem alterações pendentes';$('save').disabled=!dirty||busy||!!pendingDraft;$('draft-save').disabled=!dirty||busy||!!pendingDraft;$('import-draft').disabled=busy;$('fields').disabled=busy||!!pendingDraft;const doc=document.querySelector('.document-editor');if(doc)doc.contentEditable=String(!busy&&!pendingDraft);$('new-work').disabled=busy||!!pendingDraft;if($('new-peregrini'))$('new-peregrini').disabled=busy||!!pendingDraft; }
  function mark(){dirty=true;status();clearTimeout(draftTimer);if(!pendingDraft)draftTimer=setTimeout(saveDraft,700);}
  function lock(value){busy=value;$('fields').disabled=value;['save','download','reload','preview','new-work','new-peregrini','disconnect','draft-save','draft-restore','draft-discard'].forEach(id=>{if($(id))$(id).disabled=value;});$('work-list').querySelectorAll('button').forEach(b=>b.disabled=value);status();}
  function options(values,value){return Object.entries(values).map(([key,label])=>`<option value="${escape(key)}" ${value===key?'selected':''}>${escape(label)}</option>`).join('');}
  function list(){ $('work-list').replaceChildren();data.works.forEach((w,i)=>{const b=document.createElement('button');b.type='button';b.textContent=(w.language==='peregrini'?'☽ ':'')+(w.title||'Sem título');if(i===workIndex)b.setAttribute('aria-current','true');b.onclick=()=>{workIndex=i;formatIndex=0;render();};$('work-list').append(b);}); }
  function field(id,obj,key,parser=x=>x,event='input'){ $(id).addEventListener(event,()=>{obj[key]=parser($(id).value);mark();if(key==='title'&&obj===work())list();}); }
  function render(){
    if(data!==vocabularyData){vocabularyData=data;window.mountVocabularyEditor($('vocabulary-editor'),data,mark);}
    list();const w=work();if(!w){$('editor').innerHTML='<h2>Seu acervo está vazio</h2><p>Use “Nova obra” para começar.</p>';return;}const v=version();const peregrini=w.language==='peregrini';
    $('editor').innerHTML=`<h2>Editar obra</h2><label for="work-title">Título</label><input id="work-title" value="${escape(w.title)}"><p class="help">O endereço da obra é preservado quando você muda o título.</p><label for="work-kind">Categoria</label><select id="work-kind">${options({Ensaio:"Ensaio",Suma:"Suma",Reflexão:"Reflexão","Teoria social":"Teoria social",[w.kind]:w.kind},w.kind)}</select><label for="work-collections">Coleções (separe por ponto e vírgula)</label><input id="work-collections" list="collection-names" value="${escape((w.collections||[]).join("; "))}" placeholder="Kant; Ética"><datalist id="collection-names">${[...new Set(data.works.flatMap(x=>x.collections||[]))].map(c=>`<option value="${escape(c)}">`).join("")}</datalist><div id="collection-picks" class="collection-picks" aria-label="Associar a coleções existentes"></div><label for="work-published">Data da primeira publicação</label><input type="date" id="work-published" value="${escape(w.published||"")}"><button type="button" id="published-today">Usar a data de hoje</button><p class="help">Esta data organiza as novidades e identifica o texto mais novo de cada coleção. Novas obras recebem a data ao publicar. Para obras antigas sem data conhecida, você pode preenchê-la.</p><div class="chapter-actions"><button type="button" id="work-up" ${workIndex===0?"disabled":""}>↑ Antes na leitura</button><button type="button" id="work-down" ${workIndex===data.works.length-1?"disabled":""}>↓ Depois na leitura</button></div><label for="work-summary">Resumo</label><textarea id="work-summary" rows="3">${escape(w.summary)}</textarea><div class="variant-row"><label for="work-variant">Forma de apresentação<select id="work-variant">${w.variants.map((a,i)=>`<option value="${i}" ${i===formatIndex?'selected':''}>${a.id==='didatico'?'Didático':'Sintético'}</option>`).join('')}</select></label>${w.variants.length<2?'<button id="add-version" type="button">+ Outra apresentação</button>':''}</div><div class="row"><label for="version-status">Estado<select id="version-status">${options({andamento:'Em andamento',finalizado:'Finalizado'},v.status)}</select></label><label for="version-availability">Conteúdo disponível<select id="version-availability">${options({trecho:'Trecho',integral:'Texto integral',demonstracao:'Demonstração'},v.availability)}</select></label></div><div class="row" id="progress-fields" ${v.status==='finalizado'?'hidden':''}><label for="version-last">Última parte escrita<input id="version-last" value="${escape(v.last||'')}"></label><label for="version-next">Próxima parte<input id="version-next" value="${escape(v.next||'')}"></label></div><h3>Documento</h3><div id="document-host"></div><p><button id="delete-work" class="danger" type="button">Remover esta obra</button></p>`;
    if(peregrini){const badge=document.createElement('p');badge.className='peregrini-editor-badge';badge.textContent='Escrita original · área Peregrini';$('editor').prepend(badge);}
    const picks=$('collection-picks');
    for(const name of [...new Set(data.works.flatMap(x=>x.collections||[]))].sort((a,b)=>a.localeCompare(b,'pt-BR'))){const label=document.createElement('label'),box=document.createElement('input');box.type='checkbox';box.checked=(w.collections||[]).includes(name);box.addEventListener('change',()=>{const chosen=new Set(w.collections||[]);box.checked?chosen.add(name):chosen.delete(name);w.collections=[...chosen];$('work-collections').value=w.collections.join('; ');mark();});label.append(box,document.createTextNode(name));picks.append(label);}
    $('work-collections').addEventListener('input',()=>{const values=$('work-collections').value.split(';').map(x=>x.trim());picks.querySelectorAll('label').forEach(label=>label.querySelector('input').checked=values.includes(label.textContent));});
    $('published-today').onclick=()=>{const d=new Date();const today=[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');$('work-published').value=today;w.published=today;mark();};
    field('work-collections',w,'collections',x=>[...new Set(x.split(';').map(c=>c.trim()).filter(Boolean))]);field('work-published',w,'published',x=>x||null);for(const [id,delta]of [['work-up',-1],['work-down',1]])$(id).onclick=()=>{const target=workIndex+delta;if(target<0||target>=data.works.length)return;[data.works[workIndex],data.works[target]]=[data.works[target],data.works[workIndex]];workIndex=target;mark();render();};field('work-title',w,'title');field('work-kind',w,'kind');field('work-summary',w,'summary');field('version-status',v,'status',x=>x,'change');field('version-availability',v,'availability',x=>x,'change');field('version-last',v,'last');field('version-next',v,'next');
    $('version-status').addEventListener('change',()=>{$('progress-fields').hidden=v.status==='finalizado';});
    $('work-variant').onchange=()=>{formatIndex=Number($('work-variant').value);render();};
    if($('add-version'))$('add-version').onclick=()=>{w.variants.push(M.variant(v.id==='didatico'?'sintetico':'didatico'));formatIndex=w.variants.length-1;mark();render();};
    (peregrini?window.mountPeregriniEditor:window.mountDocumentEditor)($('document-host'),v,mark);
    $('delete-work').onclick=()=>{if(!confirm(`Remover “${w.title}” do acervo? A remoção só será publicada ao salvar no GitHub.`))return;data.works.splice(workIndex,1);workIndex=Math.max(0,workIndex-1);formatIndex=0;mark();render();};
    status();
  }
  function load(file){const parsed=M.validate(M.parse(file.text));data=parsed;base=M.clone(parsed);workIndex=0;formatIndex=0;dirty=false;$('workspace').hidden=false;$('connection').hidden=true;$('disconnect').hidden=false;$('publication').hidden=true;findDraft();render();status();try{const hash=sessionStorage.getItem('peregrini:pending-publication');if(/^[a-f0-9]{64}$/.test(hash||''))watchPublication(hash);}catch{}}
  $('connect-form').onsubmit=async e=>{e.preventDefault();const button=e.submitter||$('connect-form').querySelector('button[type=submit]'),githubToken=$('token').value,messagesKey=$('messages-key').value.trim();button.disabled=true;notice('Conectando à sua conta…');try{const file=await client.connect(githubToken);load(file);let messagesOpened=false;if(messagesKey&&window.PeregriniInbox){messagesOpened=await window.PeregriniInbox.open(messagesKey);if(!messagesOpened)$('inbox-key').value=messagesKey;}$('messages-key').value='';notice(messagesOpened?'Conectado. Mensagens e feedback estão disponíveis abaixo do editor.':'Conectado. Escolha uma obra ou abra as mensagens do autor.');}catch(e){client.disconnect();notice(e.message,true);}finally{$('token').value='';$('messages-key').value='';button.disabled=false;}};
  $('editor-form').onsubmit=e=>e.preventDefault();
  $('disconnect').onclick=()=>{if(dirty){saveDraft();if(!confirm('Encerrar a sessão? O rascunho salvo neste navegador será mantido. Se houve erro ao salvá-lo, cancele e baixe uma cópia.'))return;}clearTimeout(draftTimer);stopPublication();window.PeregriniInbox?.lock();client.disconnect();data=base=null;vocabularyData=null;$('vocabulary-editor').replaceChildren();dirty=false;$('editor').replaceChildren();$('work-list').replaceChildren();$('workspace').hidden=true;$('connection').hidden=false;$('disconnect').hidden=true;notice('Sessão encerrada.');};
  $('reload').onclick=async()=>{if(dirty){saveDraft();if(!confirm('Recarregar o acervo do GitHub? Seu rascunho local será mantido para recuperação.'))return;}clearTimeout(draftTimer);lock(true);try{const file=await client.reload(text=>M.validate(M.parse(text)));load(file);notice('Acervo atualizado a partir do GitHub.');}catch(e){notice(e.message,true);}finally{lock(false);}};
  $('save').onclick=async()=>{if(!dirty||busy||pendingDraft)return;if(!confirm('Publicar todas as alterações do acervo? Elas ficarão visíveis após a publicação terminar.'))return;saveDraft();const today=new Date(),date=`${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}-${String(today.getDate()).padStart(2,'0')}`;let next;try{next=M.prepare(data,base,date);}catch(e){notice(e.message,true);$('notice').scrollIntoView?.({block:'center'});return;}lock(true);notice('Salvando textos e vocabulário no GitHub…');try{const text=JSON.stringify(next,null,2)+'\n';const hash=await window.PeregriniPublication.digest(text);await client.save(text);data=next;base=M.clone(next);dirty=false;render();clearDraft();draftNotice('Rascunho enviado para publicação.');notice('Textos salvos no GitHub. Verificando a publicação…');watchPublication(hash);}catch(e){notice(e.message,true);}finally{lock(false);}};

  $('import-draft').onclick=()=>$('draft-file').click();
  $('draft-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>20000000)throw Error('A cópia deve ter até 20 MB.');const parsed=M.parse(await file.text()),catalog=parsed.data||parsed;M.validate(catalog,{draft:true});const list=$('import-works');list.replaceChildren();catalog.works.forEach((w,i)=>{const label=document.createElement('label'),box=document.createElement('input');box.type='checkbox';box.value=i;box.checked=true;label.append(box,document.createTextNode(w.title));list.append(label);});$('import-vocabulary-label').hidden=!catalog.peregrini; $('import-vocabulary').checked=!!catalog.peregrini; $('import-dialog').showModal();$('import-confirm').onclick=()=>{if(busy)return;const works=[...list.querySelectorAll('input:checked')].map(x=>catalog.works[Number(x.value)]);const incoming={works};if(catalog.peregrini&&$('import-vocabulary').checked)incoming.peregrini=catalog.peregrini;if(!works.length&&!incoming.peregrini){notice('Selecione uma obra ou o vocabulário para importar.',true);return;}let result;try{result=M.mergeDraft(data,incoming,parsed.base);}catch(error){notice(error.message,true);return;}data=result.data;pendingDraft=null;$('draft-recovery').hidden=true;workIndex=data.works.length-1;formatIndex=0;mark();render();saveDraft();$('import-dialog').close();notice('Obras recuperadas. Revise e clique em Publicar alterações.');};}catch(error){notice(error.message,true);}finally{e.target.value='';}};
  $('import-cancel').onclick=()=>$('import-dialog').close();
  $('draft-save').onclick=saveDraft;
  $('publication-check').onclick=()=>{stopPublication();checkPublication(false);};
  $('draft-export').onclick=()=>{if(pendingDraft)exportData(pendingDraft.data,'rascunho-peregrini.json');};
  $('draft-discard').onclick=()=>{if(!confirm('Apagar o rascunho guardado neste navegador?'))return;clearDraft();draftNotice('Rascunho descartado.');status();if(dirty)saveDraft();};
  $('draft-restore').onclick=()=>{if(!pendingDraft)return;try{if(!drafts.matches(pendingDraft,base)){const result=M.mergeDraft(base,pendingDraft.data,pendingDraft.base);pendingDraft.data=result.data;draftNotice(result.conflicts.length?'Versões conflitantes recuperadas como cópias: '+result.conflicts.join(', '):'Rascunho integrado ao acervo atual.');}M.validate(pendingDraft.data,{draft:true});data=M.clone(pendingDraft.data);pendingDraft=null;$('draft-recovery').hidden=true;workIndex=formatIndex=0;dirty=true;render();status();draftNotice('Rascunho restaurado. Ele ainda não foi publicado.');}catch(e){notice(e.message,true);}};
  $('download').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)+'\n'],{type:'application/json;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='obras-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
  $('new-work').onclick=()=>{$('new-title').value='';delete $('new-title').dataset.peregrini;$('new-dialog').showModal();$('new-title').focus();};
  if($('new-peregrini'))$('new-peregrini').onclick=()=>{$('new-title').value='';$('new-title').dataset.peregrini='true';$('new-title').placeholder='Título de referência (opcional)';$('new-dialog').showModal();$('new-title').focus();};
  $('cancel-new').onclick=()=>$('new-dialog').close();
  $('new-form').onsubmit=e=>{e.preventDefault();const input=$('new-title'),peregrini=!!input.dataset.peregrini,title=input.value.trim()||(peregrini?'Novo texto Peregrini':'Nova obra');data.works.push(peregrini?M.newPeregriniWork(data,title):M.newWork(data,title));delete input.dataset.peregrini;input.placeholder='';workIndex=data.works.length-1;formatIndex=0;mark();render();$('new-dialog').close();};
  $('preview').onclick=()=>{const w=work(),v=version();if(!w)return;const box=$('preview-content');window.MathJax?.typesetClear?.([box]);box.replaceChildren();function add(tag,text,parent=box){const el=document.createElement(tag);el.textContent=text;parent.append(el);return el;}add('h1',w.title);add('p',data.author);add('p',w.summary);function sections(cs,level){for(const c of cs){add(`h${level}`,c.title);c.paragraphs.forEach(p=>add('p',p));sections(c.subchapters||[],level+1);}}if(v.blocks){const body=document.createElement('div');if(w.language==='peregrini'){body.className='peregrini-document';body.dir='rtl';}body.innerHTML=window.PeregriniDocument.render(v.blocks);box.append(body);}else sections(v.chapters,2);$('preview-dialog').showModal();if(window.PeregriniMath?.contains(box))window.PeregriniMath.typeset(box).catch(error=>notice(error.message,true));};
  $('close-preview').onclick=()=>$('preview-dialog').close();
  window.addEventListener('pagehide',()=>{saveDraft();stopPublication();});
  window.addEventListener('beforeunload',e=>{if(dirty){saveDraft();e.preventDefault();e.returnValue='';}});
})();
